import{_ as e,o as a,c as s,a3 as o}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Comparisons","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Comparisons | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/comparisons"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/comparisons"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/comparisons"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/comparisons"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/comparisons"}]]},"headers":[],"relativePath":"xclang/guide/comparisons.md","filePath":"en/xclang/guide/comparisons.md","lastUpdated":1791227177000}'),r={name:"xclang/guide/comparisons.md"};function n(i,t,d,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="comparisons" tabindex="-1">Comparisons <a class="header-anchor" href="#comparisons" aria-label="Permalink to &quot;Comparisons&quot;">​</a></h1><p>The toolchains people use for the jobs xclang does, what each does, and where xclang differs, in both directions. Facts are as of 2026-10-06 and come from each project&#39;s own documentation, linked; corrections are welcome as <a href="https://github.com/clice-io/xclang/issues" target="_blank" rel="noreferrer">issues</a>.</p><h2 id="in-one-table" tabindex="-1">In one table <a class="header-anchor" href="#in-one-table" aria-label="Permalink to &quot;In one table&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>what it is</th><th>targets out of the box</th><th>sysroots and SDKs</th><th>C++ runtime in programs</th><th>Linux programs run on</th><th>build systems</th><th>compiler built with PGO</th></tr></thead><tbody><tr><td><strong>xclang</strong></td><td>clang, lld and six targets&#39; runtimes, prebuilt</td><td>Linux x64/arm64, Windows x64/arm64 (MinGW), macOS (from macOS)</td><td>bundled; macOS SDK from Xcode</td><td>libc++, static</td><td>glibc 2.17+</td><td>CMake package, Bazel module, conda</td><td>yes, PGO + ThinLTO, every host</td></tr><tr><td><strong>zig cc</strong> 0.17</td><td>Zig&#39;s driver around its clang</td><td>dozens: glibc, musl, MinGW, macOS, BSDs, WASI</td><td>libc sources and stubs bundled, built on first use</td><td>libc++, static</td><td>any glibc version chosen per target (default 2.31)</td><td><code>zig build</code>; <code>CC=&quot;zig cc&quot;</code></td><td>not stated</td></tr><tr><td><strong>cargo-zigbuild</strong></td><td>zig cc as cargo&#39;s linker</td><td>Linux, macOS (per its README)</td><td>through zig; macOS SDK from the user</td><td>through zig</td><td>glibc version chosen per target</td><td>cargo</td><td>(zig&#39;s)</td></tr><tr><td><strong>cross-rs</strong></td><td>cargo in Docker images with GCC cross toolchains</td><td>most of Rust&#39;s Linux, Windows and other targets</td><td>per-target images; Apple and MSVC images built by the user</td><td>libstdc++</td><td>2.31 (2.17 in <code>:centos</code> images)</td><td>cargo</td><td>no (GCC)</td></tr><tr><td><strong>llvm-mingw</strong></td><td>clang, lld, mingw-w64 and LLVM&#39;s runtimes</td><td>Windows i686, x86_64, armv7, arm64</td><td>bundled</td><td>libc++ DLL by default, static with <code>-static</code></td><td>(no Linux targets)</td><td>any, through <code>&lt;triple&gt;-clang</code> names</td><td>yes, PGO + ThinLTO</td></tr><tr><td><strong>conda-forge compilers</strong></td><td>GCC, clang, MSVC activation packages</td><td>the conda platforms, in recipes</td><td><code>sysroot_linux-*</code> packages</td><td>shared, from <code>libstdcxx</code>/<code>libcxx</code> packages via <code>run_exports</code></td><td>glibc 2.17+ (2.28 opt-in)</td><td>conda-build, rattler-build</td><td>not stated</td></tr><tr><td><strong>LLVM releases</strong></td><td>upstream binaries</td><td>the host only</td><td>none</td><td>host runtimes only</td><td>(the toolchain is built on Ubuntu 22.04)</td><td>none</td><td>Linux, macOS: PGO + ThinLTO; Windows: PGO</td></tr><tr><td><strong>distro clang + GCC cross</strong></td><td>OS packages</td><td>one package set per target</td><td>distro packages per target</td><td>libstdc++, shared</td><td>the distribution&#39;s glibc</td><td>any</td><td>depends on the distribution</td></tr><tr><td><strong>Android NDK</strong></td><td>clang and bionic sysroots</td><td>Android ABIs × API levels</td><td>bundled</td><td>libc++, static or shared</td><td>(Android)</td><td>CMake, ndk-build</td><td>yes, with BOLT</td></tr><tr><td><strong>wasi-sdk</strong></td><td>clang and wasi-libc</td><td><code>wasm32-wasip1</code>, <code>wasip2</code></td><td>bundled</td><td>libc++, static</td><td>(WASI)</td><td>CMake toolchain file</td><td>not stated</td></tr><tr><td><strong>toolchains_llvm</strong> (Bazel)</td><td>rules around LLVM&#39;s release binaries</td><td>the host; cross with a user sysroot</td><td>the user&#39;s</td><td>libc++ static natively, the sysroot&#39;s libstdc++ when cross</td><td>the sysroot&#39;s</td><td>Bazel</td><td>(LLVM&#39;s)</td></tr><tr><td><strong>hermetic_cc_toolchain</strong> (Bazel)</td><td>rules around zig cc</td><td>Linux glibc/musl, windows-gnu, macOS (weak)</td><td>through zig</td><td>libc++, static</td><td>chosen per target</td><td>Bazel</td><td>(zig&#39;s)</td></tr></tbody></table><h2 id="zig-cc" tabindex="-1">zig cc <a class="header-anchor" href="#zig-cc" aria-label="Permalink to &quot;zig cc&quot;">​</a></h2><p><a href="https://andrewkelley.me/post/zig-cc-powerful-drop-in-replacement-gcc-clang.html" target="_blank" rel="noreferrer"><code>zig cc</code></a> is the closest in spirit: one download, <code>-target</code> and nothing else, and it is where the idea of a cross-compiling clang without a sysroot to install was shown to work. It differs from xclang in how it gets there:</p><ul><li><strong>It builds the runtimes on first use.</strong> Zig ships the sources of libc++, libc++abi, libunwind, compiler-rt and of several C libraries, and builds what a target needs the first time, then caches it (<a href="https://ziglang.org/learn/overview/" target="_blank" rel="noreferrer">overview</a>). That is how it fits dozens of targets in a 55 MB download. xclang ships the six targets&#39; runtimes prebuilt (no first-build delay, the same bytes for everyone) and is to fetch other targets as prebuilt archives.</li><li><strong>It has more targets today</strong>: musl, any glibc version per target (<code>x86_64-linux-gnu.2.17</code>), the BSDs, WASI, and macOS from any host with Apple&#39;s libc headers and a <code>libSystem</code> stub (<a href="https://ziglang.org/download/0.17.0/release-notes.html" target="_blank" rel="noreferrer">0.17.0 release notes</a>). xclang has none of these yet.</li><li><strong>Its clang is Zig&#39;s.</strong> 0.17.0 has LLVM 22, with loop vectorization disabled to work around a regression since 0.16.0; xclang follows LLVM&#39;s releases with stock clang, built with PGO and ThinLTO.</li><li><strong>Runtimes</strong>: zig links libc++ statically, as xclang does, and has open issues with libc++ in more than one shared object (<a href="https://github.com/ziglang/zig/issues/24831" target="_blank" rel="noreferrer">#24831</a>); it ships no ASan runtime (<a href="https://github.com/ziglang/zig/issues/11403" target="_blank" rel="noreferrer">#11403</a>), and its <code>windows-msvc</code> target uses an installed Visual Studio. xclang has ASan, TSan, LSan, UBSan and libFuzzer for Linux and macOS.</li><li><strong>Integration</strong>: zig cc is a drop-in <code>CC</code>; xclang adds a CMake package (with <code>import std</code>), a Bazel module and libclang.</li></ul><p>Zig&#39;s issue tracker moved to Codeberg in November 2025; the GitHub issues above are as they were then.</p><h2 id="cargo-zigbuild-and-cross-rs" tabindex="-1">cargo-zigbuild and cross-rs <a class="header-anchor" href="#cargo-zigbuild-and-cross-rs" aria-label="Permalink to &quot;cargo-zigbuild and cross-rs&quot;">​</a></h2><p><a href="https://github.com/rust-cross/cargo-zigbuild" target="_blank" rel="noreferrer">cargo-zigbuild</a> makes zig cc cargo&#39;s C compiler and linker; its README lists Linux and macOS targets, and a glibc version per target. <a href="https://github.com/cross-rs/cross" target="_blank" rel="noreferrer">cross-rs</a> runs cargo inside Docker or Podman images that hold a GCC cross toolchain per target, and <code>cross test</code> runs tests under QEMU; its default images have glibc 2.31 (2.17 in <code>:centos</code> ones), and it provides no images for Apple targets &quot;due to licensing reasons&quot;.</p><p>xclang is to do for cargo what cargo-zigbuild does, with stock clang and xclang&#39;s runtimes; today that is a documented recipe, not a helper (<a href="./../integrations/cargo">Rust and cargo</a>). Unlike cross-rs, it needs no container and runs natively on Windows and macOS hosts; unlike cross-rs, it runs no tests under emulation.</p><h2 id="llvm-mingw" tabindex="-1">llvm-mingw <a class="header-anchor" href="#llvm-mingw" aria-label="Permalink to &quot;llvm-mingw&quot;">​</a></h2><p><a href="https://github.com/mstorsjo/llvm-mingw" target="_blank" rel="noreferrer">llvm-mingw</a> is clang, lld, mingw-w64 and LLVM&#39;s runtimes for Windows, from Linux, macOS and Windows hosts; xclang&#39;s MinGW targets are the same idea, and its sysroots use mingw-w64 as llvm-mingw does. llvm-mingw has more Windows architectures (i686, armv7, and arm64ec in its scripts), an msvcrt variant for older Windows, ASan on x86, and Control Flow Guard. It links libc++ and libunwind as DLLs unless <code>-static</code> is given (<a href="https://github.com/mstorsjo/llvm-mingw/issues/333" target="_blank" rel="noreferrer">#333</a>); xclang links them in. Its releases are built with PGO and ThinLTO too. It has no Linux or macOS targets.</p><h2 id="conda-forge-s-compilers" tabindex="-1">conda-forge&#39;s compilers <a class="header-anchor" href="#conda-forge-s-compilers" aria-label="Permalink to &quot;conda-forge&#39;s compilers&quot;">​</a></h2><p>conda-forge&#39;s <code>cxx-compiler</code> is GCC on Linux, clang on macOS and MSVC on Windows, made to build conda packages: the C++ runtime is a shared library from a package (<code>libstdcxx</code>, <code>libcxx</code>), which <code>run_exports</code> adds to every package built with it, and the Linux baseline is glibc 2.17 through <code>sysroot_linux-*</code> packages (<a href="https://conda-forge.org/docs/maintainer/knowledge_base/" target="_blank" rel="noreferrer">knowledge base</a>). That is right for an environment where conda provides the runtimes, and wrong for a program that leaves it. xclang is a conda package too, but is not a compiler for conda-forge packages: it links its runtimes into every program and has no <code>run_exports</code>.</p><h2 id="llvm-s-release-binaries" tabindex="-1">LLVM&#39;s release binaries <a class="header-anchor" href="#llvm-s-release-binaries" aria-label="Permalink to &quot;LLVM&#39;s release binaries&quot;">​</a></h2><p><a href="https://github.com/llvm/llvm-project/releases/tag/llvmorg-23.1.2" target="_blank" rel="noreferrer">LLVM&#39;s releases</a> are clang, lld and the runtimes for the host, built with PGO and ThinLTO on Linux and macOS (<code>clang/cmake/caches/Release.cmake</code>) and with PGO on Windows, where LTO is off. They carry no sysroot for another target, so a cross build needs one from elsewhere, and their own size is 0.9 to 2 GB an archive. xclang 23.1.2.1 was built by them; xclang&#39;s archives are 95 to 128 MB, carry six targets, and run on glibc 2.17. On compile speed they are close: <a href="./why-xclang#fast">Why xclang</a> has the numbers.</p><h2 id="distribution-clang-and-gcc-cross-toolchains" tabindex="-1">Distribution clang and GCC cross toolchains <a class="header-anchor" href="#distribution-clang-and-gcc-cross-toolchains" aria-label="Permalink to &quot;Distribution clang and GCC cross toolchains&quot;">​</a></h2><p>On Debian, <code>crossbuild-essential-arm64</code> brings <code>aarch64-linux-gnu-g++</code> and an arm64 glibc of the distribution&#39;s version (<a href="https://packages.debian.org/trixie/crossbuild-essential-arm64" target="_blank" rel="noreferrer">packages.debian.org</a>), <code>g++-mingw-w64</code> a MinGW GCC; apt.llvm.org has every clang version. They are the default on a Linux machine and well maintained. Their programs need the distribution&#39;s glibc or newer and <code>libstdc++.so.6</code>, a MinGW GCC&#39;s need <code>libstdc++-6.dll</code> and <code>libgcc_s_seh-1.dll</code> unless linked with <code>-static</code>, each target is another set of packages, and they exist on Linux only.</p><h2 id="android-ndk-and-wasi-sdk-the-precedents" tabindex="-1">Android NDK and wasi-sdk: the precedents <a class="header-anchor" href="#android-ndk-and-wasi-sdk-the-precedents" aria-label="Permalink to &quot;Android NDK and wasi-sdk: the precedents&quot;">​</a></h2><p>Both are one clang with bundled sysroots, the shape xclang has for desktop targets. The <a href="https://developer.android.com/ndk/guides/other_build_systems" target="_blank" rel="noreferrer">NDK</a> takes the target and API level in <code>--target=aarch64-linux-android21</code>, and its libc++ is static by default in CMake. Its <a href="https://developer.android.com/ndk/guides/cpp-support" target="_blank" rel="noreferrer">C++ library support</a> page states the rule xclang&#39;s static runtimes also follow: &quot;you can only use a static variant of the C++ runtime if you have one and only one shared library in your application&quot;. <a href="https://github.com/WebAssembly/wasi-sdk" target="_blank" rel="noreferrer">wasi-sdk</a> is &quot;builds configured to set the default target and sysroot&quot;, which is what a config file per target does in xclang. Android&#39;s own clang is built with PGO, LTO and BOLT.</p><h2 id="bazel-toolchains" tabindex="-1">Bazel toolchains <a class="header-anchor" href="#bazel-toolchains" aria-label="Permalink to &quot;Bazel toolchains&quot;">​</a></h2><p><a href="https://github.com/bazel-contrib/toolchains_llvm" target="_blank" rel="noreferrer">toolchains_llvm</a> downloads LLVM&#39;s release for the host; it cross-compiles with a sysroot the user brings and then links that sysroot&#39;s libstdc++. <a href="https://github.com/uber/hermetic_cc_toolchain" target="_blank" rel="noreferrer">hermetic_cc_toolchain</a> is built on zig cc and has its targets, with macOS support &quot;not well tested&quot; and no macOS SDK. xclang&#39;s <a href="./../integrations/bazel">Bazel module</a> brings the sysroots itself, registers a toolchain per (host, target) pair, keeps its actions free of absolute paths, and adds <code>import std</code>, sanitizer features and libclang.</p><h2 id="what-xclang-does-not-do" tabindex="-1">What xclang does not do <a class="header-anchor" href="#what-xclang-does-not-do" aria-label="Permalink to &quot;What xclang does not do&quot;">​</a></h2><ul><li>Targets beyond the six: no musl, Android, iOS, WebAssembly, BSDs or bare metal yet; zig cc, the NDK and wasi-sdk have them.</li><li>MSVC-ABI targets, and macOS from Linux or Windows: in research.</li><li>Run tests for other targets under emulation, as cross-rs does.</li><li>Older Windows (msvcrt, Windows 7), as llvm-mingw does.</li><li>A shared C++ runtime across shared libraries.</li><li>Build runtimes from source with other options (MemorySanitizer, libc++ hardening, a libc++ ABI of one&#39;s own): planned.</li></ul>',25)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
